begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(16);
insert into auth.users(id,email) values ('43100000-0000-4000-8000-000000000001','slots-owner@example.test'),('43100000-0000-4000-8000-000000000002','slots-doctor@example.test'),('43100000-0000-4000-8000-000000000003','slots-assistant@example.test'),('43100000-0000-4000-8000-000000000004','slots-other@example.test');
insert into public.clinics(id,name,timezone) values ('43200000-0000-4000-8000-000000000001','Slots A','America/Mexico_City'),('43200000-0000-4000-8000-000000000002','Slots B','America/New_York');
insert into public.clinic_members(id,clinic_id,user_id,role,status) values ('43300000-0000-4000-8000-000000000001','43200000-0000-4000-8000-000000000001','43100000-0000-4000-8000-000000000001','owner','active'),('43300000-0000-4000-8000-000000000002','43200000-0000-4000-8000-000000000001','43100000-0000-4000-8000-000000000002','doctor','active'),('43300000-0000-4000-8000-000000000003','43200000-0000-4000-8000-000000000001','43100000-0000-4000-8000-000000000003','assistant','active'),('43300000-0000-4000-8000-000000000004','43200000-0000-4000-8000-000000000002','43100000-0000-4000-8000-000000000004','doctor','active');
insert into public.patients(id,clinic_id,full_name,first_names,internal_identifier) values ('43400000-0000-4000-8000-000000000001','43200000-0000-4000-8000-000000000001','Slots Patient','Slots','PAC-SLOT0001');
insert into public.professional_availability_rules(clinic_id,clinic_member_id,weekday,start_time,end_time,effective_from) values ('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002',1,'09:00','13:00','2035-01-01'),('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002',1,'15:00','18:00','2035-01-01');
select extensions.ok(has_function_privilege('authenticated','public.get_professional_available_slots(uuid,uuid,date,integer,integer,integer,integer)','execute') and not has_function_privilege('anon','public.get_professional_available_slots(uuid,uuid,date,integer,integer,integer,integer)','execute'),'slot RPC is authenticated-only');
select extensions.ok((select prosecdef and proconfig @> array['search_path=public, pg_temp'] from pg_proc where oid='public.get_professional_available_slots(uuid,uuid,date,integer,integer,integer,integer)'::regprocedure),'slot RPC has fixed definer boundary');
set local role authenticated; select set_config('request.jwt.claim.sub','43100000-0000-4000-8000-000000000001',true);
select extensions.is((select count(*)::int from public.get_professional_available_slots('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','2035-09-17',30,30,0,0)),14,'two recurring windows generate slots');
select extensions.lives_ok($$insert into public.professional_availability_exceptions(clinic_id,clinic_member_id,exception_type,start_at,end_at) values ('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','unavailable','2035-09-17 18:30+00','2035-09-17 20:30+00')$$,'owner writes an exception');
select extensions.is((select count(*)::int from public.get_professional_available_slots('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','2035-09-17',30,30,0,0)),13,'unavailable exception removes overlapping slots');
select extensions.lives_ok($$insert into public.professional_availability_exceptions(clinic_id,clinic_member_id,exception_type,start_at,end_at) values ('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','available','2035-09-18 00:00+00','2035-09-18 02:00+00')$$,'owner creates extraordinary opening');
select extensions.is((select count(*)::int from public.get_professional_available_slots('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','2035-09-17',30,30,0,0)),17,'available exception extends slots after day boundary conversion');
select extensions.lives_ok($$insert into public.professional_availability_exceptions(clinic_id,clinic_member_id,exception_type,start_at,end_at) values ('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','unavailable','2035-09-18 00:30+00','2035-09-18 01:00+00')$$,'unavailable may overlap an extraordinary opening');
select extensions.is((select count(*)::int from public.get_professional_available_slots('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','2035-09-17',30,30,0,0)),16,'unavailable wins over available exception');
select extensions.throws_ok($$insert into public.professional_availability_exceptions(clinic_id,clinic_member_id,exception_type,start_at,end_at) values ('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','unavailable','2035-09-17 20:00+00','2035-09-17 20:00+00')$$,'23514',null,'invalid exception range rejected');
reset role; insert into public.appointments(id,clinic_id,patient_id,doctor_id,title,starts_at,ends_at,status) values ('43500000-0000-4000-8000-000000000001','43200000-0000-4000-8000-000000000001','43400000-0000-4000-8000-000000000001','43100000-0000-4000-8000-000000000002','busy','2035-09-17 21:00+00','2035-09-17 21:30+00','scheduled'),('43500000-0000-4000-8000-000000000002','43200000-0000-4000-8000-000000000001','43400000-0000-4000-8000-000000000001','43100000-0000-4000-8000-000000000002','cancelled','2035-09-17 22:00+00','2035-09-17 22:30+00','scheduled'); update public.appointments set status='cancelled' where id='43500000-0000-4000-8000-000000000002';
set local role authenticated; select set_config('request.jwt.claim.sub','43100000-0000-4000-8000-000000000001',true);
select extensions.ok(not exists(select 1 from public.get_professional_available_slots('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','2035-09-17',30,30,10,10) where local_start='15:30'),'appointment buffers block slots');
select extensions.ok(exists(select 1 from public.get_professional_available_slots('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','2035-09-17',30,30,0,0) where local_start='16:00'),'cancelled appointment does not block');
select extensions.is((select count(*)::int from public.get_professional_available_slots('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','2035-09-18',30,15,0,0)),0,'day without recurring rules or openings returns empty list');
select extensions.throws_ok($$select * from public.get_professional_available_slots('43200000-0000-4000-8000-000000000002','43300000-0000-4000-8000-000000000002','2035-09-17',30,30,0,0)$$,'42501',null,'cross-tenant lookup rejected');
reset role; insert into public.professional_availability_rules(clinic_id,clinic_member_id,weekday,start_time,end_time,effective_from) values ('43200000-0000-4000-8000-000000000002','43300000-0000-4000-8000-000000000004',7,'09:00','10:00','2035-01-01');
set local role authenticated; select set_config('request.jwt.claim.sub','43100000-0000-4000-8000-000000000004',true);
select extensions.is((select start_at from public.get_professional_available_slots('43200000-0000-4000-8000-000000000002','43300000-0000-4000-8000-000000000004','2035-03-11',30,30,0,0) limit 1),timestamptz '2035-03-11 13:00+00','DST clinic-local morning resolves to the correct instant');
select set_config('request.jwt.claim.sub','43100000-0000-4000-8000-000000000003',true);
select extensions.throws_ok($$insert into public.professional_availability_exceptions(clinic_id,clinic_member_id,exception_type,start_at,end_at) values ('43200000-0000-4000-8000-000000000001','43300000-0000-4000-8000-000000000002','unavailable','2035-09-18 18:00+00','2035-09-18 19:00+00')$$,'42501',null,'assistant cannot write exceptions');
select extensions.finish(); rollback;
